 tip text NOT NULL CHECK(tip ~ '^[a-f0-9]{64}$'),
 pool text NOT NULL CHECK(pool ~ '^[1-9A-HJ-NP-Za-km-z]{32,44}$'),
 epoch bigint NOT NULL DEFAULT 0 CHECK(epoch>=0),
