);
CREATE TABLE liquidity_fencing_private.reservations (
 operation uuid NOT NULL REFERENCES liquidity_fencing_private.claims,
 ordinal integer NOT NULL CHECK(ordinal>0), reserved_at timestamptz NOT NULL,
