CREATE FUNCTION liquidity_fencing_private.admit(p_operation uuid,p_epoch bigint,p_tip text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,liquidity_fencing_private AS $$
